#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> v = {10, 20, 30};
    for (auto it = v.begin(); it != v.end(); ++it) {
        cout << *it << " ";
    }
    cout << endl;
    for (auto it = v.rbegin(); it != v.rend(); ++it) {
        cout << *it << " ";
    }
    cout << endl;
    return 0;
}

#include <iostream>
#include <iterator>
#include <list>
using namespace std;

int main() {
    list<int> items = {4, 8, 15, 16};
    auto it = next(items.begin(), 2);
    cout << *it << endl;
    cout << distance(items.begin(), it) << endl;
    return 0;
}

